package com.example.starter.domain;

/**
 * 批次审查流程状态。
 */
public enum ReviewStatus {
    /** 资料缺项，已一次性告知补正，等待企业在 5 个工作日内补正 */
    PENDING_CORRECTION,
    /** 资料审查通过（资料目录核对齐全） */
    DOCUMENT_REVIEWED,
    /** 检验核对完成（检验链已逐项复算） */
    INSPECTION_CHECKED,
    /** 综合评定通过 */
    EVALUATION_PASSED,
    /** 综合评定不通过（终态之一） */
    REJECTED,
    /** 公示中（签发结论公示 7 个自然日） */
    PUBLICIZING,
    /** 公示期内异议受理，转复核 */
    OBJECTION_REVIEW,
    /** 逾期未补正，按撤回处理（终态之一） */
    WITHDRAWN,
    /** 已签发归档（终态） */
    ISSUED
}

package com.example.starter.domain;

/**
 * 公示记录状态。
 */
public enum PublicityStatus {
    /** 公示中 */
    PUBLICIZING,
    /** 异议受理，转复核 */
    OBJECTION_REVIEW,
    /** 公示期满生效 */
    EFFECTIVE
}

package com.example.starter.domain;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 批次审查主表 PO。一个批号全局唯一对应一个审查流程。
 */
public class Review {

    private Long id;
    private String enterpriseName;
    private String productName;
    private String batchNo;
    private ReviewStatus status;
    /** 当前已受理的资料目录代码，JSON 数组文本。 */
    private String documentsJson;
    /** 一次性告知的缺项资料代码，JSON 数组文本；空值表示无缺项告知。 */
    private String missingJson;
    private Instant declaredAt;
    /** 补正告知日期（Asia/Shanghai），空值表示未告知。 */
    private LocalDate correctionNoticeDate;
    /** 补正截止日期（告知后第 5 个工作日，恰当日提交仍受理）。 */
    private LocalDate correctionDeadline;
    private Instant correctedAt;
    /** 公示开始 UTC 日期。 */
    private LocalDate publicityStartUtc;
    /** 公示期满 UTC 日期（开始日 + 7 个自然日）。 */
    private LocalDate publicityEndUtc;
    /** 综合评定结论 PASS/FAIL，空值表示尚未评定。 */
    private String conclusion;
    private Instant issuedAt;
    private Instant createdAt;
    private Instant updatedAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getEnterpriseName() {
        return enterpriseName;
    }

    public void setEnterpriseName(String enterpriseName) {
        this.enterpriseName = enterpriseName;
    }

    public String getProductName() {
        return productName;
    }

    public void setProductName(String productName) {
        this.productName = productName;
    }

    public String getBatchNo() {
        return batchNo;
    }

    public void setBatchNo(String batchNo) {
        this.batchNo = batchNo;
    }

    public ReviewStatus getStatus() {
        return status;
    }

    public void setStatus(ReviewStatus status) {
        this.status = status;
    }

    public String getDocumentsJson() {
        return documentsJson;
    }

    public void setDocumentsJson(String documentsJson) {
        this.documentsJson = documentsJson;
    }

    public String getMissingJson() {
        return missingJson;
    }

    public void setMissingJson(String missingJson) {
        this.missingJson = missingJson;
    }

    public Instant getDeclaredAt() {
        return declaredAt;
    }

    public void setDeclaredAt(Instant declaredAt) {
        this.declaredAt = declaredAt;
    }

    public LocalDate getCorrectionNoticeDate() {
        return correctionNoticeDate;
    }

    public void setCorrectionNoticeDate(LocalDate correctionNoticeDate) {
        this.correctionNoticeDate = correctionNoticeDate;
    }

    public LocalDate getCorrectionDeadline() {
        return correctionDeadline;
    }

    public void setCorrectionDeadline(LocalDate correctionDeadline) {
        this.correctionDeadline = correctionDeadline;
    }

    public Instant getCorrectedAt() {
        return correctedAt;
    }

    public void setCorrectedAt(Instant correctedAt) {
        this.correctedAt = correctedAt;
    }

    public LocalDate getPublicityStartUtc() {
        return publicityStartUtc;
    }

    public void setPublicityStartUtc(LocalDate publicityStartUtc) {
        this.publicityStartUtc = publicityStartUtc;
    }

    public LocalDate getPublicityEndUtc() {
        return publicityEndUtc;
    }

    public void setPublicityEndUtc(LocalDate publicityEndUtc) {
        this.publicityEndUtc = publicityEndUtc;
    }

    public String getConclusion() {
        return conclusion;
    }

    public void setConclusion(String conclusion) {
        this.conclusion = conclusion;
    }

    public Instant getIssuedAt() {
        return issuedAt;
    }

    public void setIssuedAt(Instant issuedAt) {
        this.issuedAt = issuedAt;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(Instant updatedAt) {
        this.updatedAt = updatedAt;
    }
}

package com.example.starter.domain;

/**
 * 检验项目明细 PO（检验链，可逐项复算）。
 */
public class InspectionRecord {

    private Long id;
    private Long reviewId;
    private String itemCode;
    private String itemName;
    /** 效力/无菌/异常毒性为关键项目。 */
    private boolean critical;
    /** 实测值文本（数值或“无菌/有菌”）。 */
    private String measuredValue;
    /** 限值文本（含等号边界）。 */
    private String limitValue;
    /** 判定方式 GTE/LTE/EQ/RANGE。 */
    private String comparison;
    /** RANGE 判定上限（含边界），其余方式为空。 */
    private String limitMax;
    private boolean qualified;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getReviewId() {
        return reviewId;
    }

    public void setReviewId(Long reviewId) {
        this.reviewId = reviewId;
    }

    public String getItemCode() {
        return itemCode;
    }

    public void setItemCode(String itemCode) {
        this.itemCode = itemCode;
    }

    public String getItemName() {
        return itemName;
    }

    public void setItemName(String itemName) {
        this.itemName = itemName;
    }

    public boolean isCritical() {
        return critical;
    }

    public void setCritical(boolean critical) {
        this.critical = critical;
    }

    public String getMeasuredValue() {
        return measuredValue;
    }

    public void setMeasuredValue(String measuredValue) {
        this.measuredValue = measuredValue;
    }

    public String getLimitValue() {
        return limitValue;
    }

    public void setLimitValue(String limitValue) {
        this.limitValue = limitValue;
    }

    public String getComparison() {
        return comparison;
    }

    public void setComparison(String comparison) {
        this.comparison = comparison;
    }

    public String getLimitMax() {
        return limitMax;
    }

    public void setLimitMax(String limitMax) {
        this.limitMax = limitMax;
    }

    public boolean isQualified() {
        return qualified;
    }

    public void setQualified(boolean qualified) {
        this.qualified = qualified;
    }
}

package com.example.starter.domain;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 公示记录 PO（公示链，可复算）。
 */
public class PublicityRecord {

    private Long id;
    private Long reviewId;
    private LocalDate startUtcDate;
    private LocalDate endUtcDate;
    private PublicityStatus status;
    private Instant objectionAt;
    private Instant effectiveAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getReviewId() {
        return reviewId;
    }

    public void setReviewId(Long reviewId) {
        this.reviewId = reviewId;
    }

    public LocalDate getStartUtcDate() {
        return startUtcDate;
    }

    public void setStartUtcDate(LocalDate startUtcDate) {
        this.startUtcDate = startUtcDate;
    }

    public LocalDate getEndUtcDate() {
        return endUtcDate;
    }

    public void setEndUtcDate(LocalDate endUtcDate) {
        this.endUtcDate = endUtcDate;
    }

    public PublicityStatus getStatus() {
        return status;
    }

    public void setStatus(PublicityStatus status) {
        this.status = status;
    }

    public Instant getObjectionAt() {
        return objectionAt;
    }

    public void setObjectionAt(Instant objectionAt) {
        this.objectionAt = objectionAt;
    }

    public Instant getEffectiveAt() {
        return effectiveAt;
    }

    public void setEffectiveAt(Instant effectiveAt) {
        this.effectiveAt = effectiveAt;
    }
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 企业-品种维度受理状态 PO。连续 3 批不合格触发暂停受理并转核查。
 */
public class EnterpriseProductStatus {

    private Long id;
    private String enterpriseName;
    private String productName;
    /** 连续不合格批次数；任一合格批评定后清零，恰为 3 触发暂停。 */
    private int consecutiveFailed;
    private boolean suspended;
    private Instant suspendedAt;
    private Instant updatedAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getEnterpriseName() {
        return enterpriseName;
    }

    public void setEnterpriseName(String enterpriseName) {
        this.enterpriseName = enterpriseName;
    }

    public String getProductName() {
        return productName;
    }

    public void setProductName(String productName) {
        this.productName = productName;
    }

    public int getConsecutiveFailed() {
        return consecutiveFailed;
    }

    public void setConsecutiveFailed(int consecutiveFailed) {
        this.consecutiveFailed = consecutiveFailed;
    }

    public boolean isSuspended() {
        return suspended;
    }

    public void setSuspended(boolean suspended) {
        this.suspended = suspended;
    }

    public Instant getSuspendedAt() {
        return suspendedAt;
    }

    public void setSuspendedAt(Instant suspendedAt) {
        this.suspendedAt = suspendedAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(Instant updatedAt) {
        this.updatedAt = updatedAt;
    }
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * requestId 幂等记录 PO。指纹覆盖 requestId 与全部业务字段。
 */
public class IdempotencyRecord {

    private String requestId;
    /** 操作类型 DECLARE/CORRECT/ISSUE。 */
    private String operation;
    private String fingerprint;
    private int httpStatus;
    private String responseJson;
    private Instant createdAt;

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public String getOperation() {
        return operation;
    }

    public void setOperation(String operation) {
        this.operation = operation;
    }

    public String getFingerprint() {
        return fingerprint;
    }

    public void setFingerprint(String fingerprint) {
        this.fingerprint = fingerprint;
    }

    public int getHttpStatus() {
        return httpStatus;
    }

    public void setHttpStatus(int httpStatus) {
        this.httpStatus = httpStatus;
    }

    public String getResponseJson() {
        return responseJson;
    }

    public void setResponseJson(String responseJson) {
        this.responseJson = responseJson;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }
}

package com.example.starter.domain;

import java.time.Instant;

/**
 * 审查事件流水 PO（含迟到资料事件，可随审查链复算）。
 */
public class ReviewEvent {

    private Long id;
    private Long reviewId;
    private String eventType;
    private String payload;
    private Instant eventAt;
    private Instant createdAt;

    public ReviewEvent() {
    }

    public ReviewEvent(Long reviewId, String eventType, String payload, Instant eventAt) {
        this.reviewId = reviewId;
        this.eventType = eventType;
        this.payload = payload;
        this.eventAt = eventAt;
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getReviewId() {
        return reviewId;
    }

    public void setReviewId(Long reviewId) {
        this.reviewId = reviewId;
    }

    public String getEventType() {
        return eventType;
    }

    public void setEventType(String eventType) {
        this.eventType = eventType;
    }

    public String getPayload() {
        return payload;
    }

    public void setPayload(String payload) {
        this.payload = payload;
    }

    public Instant getEventAt() {
        return eventAt;
    }

    public void setEventAt(Instant eventAt) {
        this.eventAt = eventAt;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }
}

