        }
    }

    /** 设定带标签线程读取的固定业务时刻（测试竞态用）。 */
    public void setTaggedTime(String tag, Instant instant) {
        synchronized (taggedTimes) {
            taggedTimes.put(tag, instant);
        }
    }
