    /**
     * 业务执行完成后，在同一事务内将占位记录定稿为首次结果。
     */
    public void finalize(String requestId, int httpStatus, String responseJson) {
        jdbc.update("""
                        UPDATE idempotency_record
                        SET http_status = ?, response_json = ?
                        WHERE request_id = ?
                        """,
                httpStatus, responseJson, requestId);
    }

    /**
     * 插入首次幂等记录。
     *
     * @return true 插入成功；false 表示 requestId 已被占用（并发首请求竞争落败）
     */
    public boolean insert(IdempotencyRecord record) {
        try {
            jdbc.update("""
                    INSERT INTO idempotency_record
                        (request_id, operation, fingerprint, http_status, response_json, created_at)
                    VALUES (?, ?, ?, ?, ?, ?)
                    """,
                    record.getRequestId(),
                    record.getOperation(),
                    record.getFingerprint(),
                    record.getHttpStatus(),
                    record.getResponseJson(),
                    Timestamp.from(record.getCreatedAt()));
            return true;
        } catch (DuplicateKeyException ex) {
            return false;
        }
    }
}

